package com.wheelwright.evidence.v2.portfolio;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static org.assertj.core.api.Assertions.*;
class TacticalFieldDependenciesTest {
 final PortfolioOrderEvaluationTest fixture;TacticalFieldDependenciesTest()throws Exception{fixture=new PortfolioOrderEvaluationTest();}
 ObjectNode coverage(ObjectNode c,ObjectNode p){var r=obj();var balances=array();for(var leaf:leaves(c.path("composition"))){var b=obj().put("status","RECONCILED");b.set("currentConstructions",array().add(c.path("self")));b.set("inventory",obj().set("holding",leaf.at("/allocation/holding")));balances.add(b);}r.set("balances",balances);r.set("coverageAssessments",array().add(obj().put("status","INSUFFICIENT").set("obligations",array().add(p.path("self")))));return r;}

 ObjectNode position(ObjectNode c){var p=fixture.position(c);p.set("currentConstruction",c.path("self"));p.set("allocation",obj().put("status","UNKNOWN"));p.set("warnings",array());return p;}
 void clearBasis(ObjectNode c){for(var l:leaves(c.path("composition")))((ObjectNode)l.path("allocation")).set("basis",unknown("MONEY",fixture.now.toString(),"BASIS_ATTRIBUTION_UNKNOWN"));}
 Map<String,ObjectNode> quotes(ObjectNode c){var result=new HashMap<String,ObjectNode>();for(var l:leaves(c.path("composition"))){var q=obj().put("freshness","CURRENT");q.set("mid",metric(new BigDecimal(l.path("side").asText().equals("LONG")?"0.5":"1"),"PRICE","USD",fixture.now.toString(),"TEST_OBSERVATION","QUALIFIED",array()));result.put(l.at("/instrument/href").asText(),q);var spot=obj().put("freshness","CURRENT");spot.set("mid",metric(new BigDecimal("10"),"PRICE","USD",fixture.now.toString(),"TEST_SPOT","QUALIFIED",array()));spot.set("bid",spot.path("mid").deepCopy());spot.set("ask",spot.path("mid").deepCopy());result.put(l.at("/terms/underlying/href").asText(),spot);}return result;}
 @Test void condorNoOpeningKeepsContractGeometryDteAndNoInventedEconomics(){var c=fixture.creditConstruction();clearBasis(c);var p=position(c);PortfolioReadService.propagate(p,coverage(c,p),c);assertThat(p.at("/evaluation/payoff/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");assertThat(p.at("/evaluation/payoff/geometry/boundaries")).hasSize(4);assertThat(p.at("/evaluation/timeline/remainingDays/value").isNull()).isFalse();assertThat(p.at("/evaluation/openingCashFlow/value").isNull()).isTrue();assertThat(p.at("/evaluation/grossUnrealizedPl/value").isNull()).isTrue();assertThat(p.at("/allocation/status").asText()).isEqualTo("RECONCILED");assertThat(p.path("warnings").toString()).contains("COVERAGE_INSUFFICIENT");}
 @Test void independentlyAdmittedVerticalEntryAndCompatibleMarksSurviveUnrelatedCashCoverage(){var c=fixture.creditConstruction();var group=(ObjectNode)c.path("composition");var children=array();for(var l:leaves(group))if(l.at("/terms/right").asText().equals("PUT")){l.put("quantity","1");((ObjectNode)l.path("allocation")).put("quantity","1");((ObjectNode)l.at("/allocation/basis")).put("value",l.path("side").asText().equals("LONG")?"100":"300");children.add(l);}group.set("children",children);assertThat(children).hasSize(2);var opening=fixture.order(c,true);var closing=fixture.order(c,false);clearBasis(c);var p=position(c);p.set("evaluation",PortfolioMath.evaluate(c,quotes(c),fixture.now));PortfolioOrderEvaluation.apply(p,c,List.of(opening,closing),fixture.now);assertThat(number(p.at("/evaluation/openingCashFlow/value"))).isEqualByComparingTo("200");assertThat(number(p.at("/evaluation/grossUnrealizedPl/value"))).isEqualByComparingTo("150");var before=p.path("evaluation").deepCopy();PortfolioReadService.propagate(p,coverage(c,p),c);assertThat(p.path("evaluation")).isEqualTo(before);assertThat(p.at("/evaluation/payoff/geometry/valueKind").asText()).isEqualTo("GROSS_PL");}
 @Test void currentSpotDoesNotRescueUnassociatedOpeningAndAbsentMarketDoesNotEraseContracts(){var c=fixture.creditConstruction();var opening=fixture.order(c,true);opening.value().set("associations",array());clearBasis(c);var p=position(c);p.set("evaluation",PortfolioMath.evaluate(c,quotes(c),fixture.now));PortfolioOrderEvaluation.apply(p,c,List.of(opening),fixture.now);PortfolioReadService.propagate(p,coverage(c,p),c);assertThat(p.at("/evaluation/spot/value").isNull()).isFalse();assertThat(p.at("/evaluation/timeline/openedAt").isNull()).isTrue();assertThat(p.at("/evaluation/openingCashFlow/value").isNull()).isTrue();var missing=position(c);PortfolioReadService.propagate(missing,coverage(c,missing),c);assertThat(missing.at("/evaluation/spot/value").isNull()).isTrue();assertThat(missing.at("/evaluation/payoff/geometry").isObject()).isTrue();}
 @Test void historicalBracketReferenceNeverCreatesOpeningOriginOrRescuesMultipleCandidates(){var c=fixture.creditConstruction();var first=fixture.order(c,true);var second=fixture.order(c,true);for(var o:List.of(first,second)){o.value().set("associations",array());o.value().put("brokerGroupId","native-bracket");o.value().set("brokerGroupStructure",obj().put("type","OTOCO").put("role","TRIGGER"));}clearBasis(c);var p=position(c);PortfolioOrderEvaluation.apply(p,c,List.of(first,second),fixture.now);assertThat(p.at("/evaluation/openingCashFlow/value").isNull()).isTrue();assertThat(p.at("/evaluation/timeline/openedAt").isNull()).isTrue();}
 @Test void staleTargetAndPartialQuantityNeverInheritOpeningEconomics(){
  for(String defect:List.of("STALE_TARGET","PARTIAL_FILL","PARTIAL_REMAINDER")){
   var c=fixture.creditConstruction();var opening=fixture.order(c,true);
   if(defect.equals("STALE_TARGET"))((ObjectNode)opening.value().path("associations").get(0)).set("target",link("/v2/constructions/"+UUID.randomUUID()));
   if(defect.equals("PARTIAL_FILL"))((ObjectNode)opening.value().at("/legs/0/fills/0")).put("quantity","0.5");
   if(defect.equals("PARTIAL_REMAINDER"))for(var l:opening.value().path("legs")){((ObjectNode)l).put("requestedQuantity","2");((ObjectNode)l.path("fills").get(0)).put("quantity","2");}
   clearBasis(c);var p=position(c);p.set("evaluation",PortfolioMath.evaluate(c,quotes(c),fixture.now));PortfolioOrderEvaluation.apply(p,c,List.of(opening),fixture.now);PortfolioReadService.propagate(p,coverage(c,p),c);assertThat(p.at("/evaluation/openingCashFlow/value").isNull()).as(defect).isTrue();assertThat(p.at("/evaluation/timeline/openedAt").isNull()).as(defect).isTrue();assertThat(p.at("/evaluation/spot/value").isNull()).as(defect).isFalse();assertThat(p.at("/evaluation/payoff/geometry/valueKind").asText()).as(defect).isEqualTo("TERMINAL_VALUE");
  }
 }
}
